{
  "findings": [
    {
      "check_id": "CKV_AWS_42",
      "title": "Ensure Cognito Identity Pool has minimal permissions with IAM roles",
      "resource": "aws_cognito_identity_pool.pass",
      "severity": "MEDIUM",
      "explanation": "The Cognito Identity Pool is not configured with specific IAM roles for authenticated and unauthenticated identities, potentially allowing overly permissive access."
    }
  ],
  "patched_code": "resource "aws_cognito_identity_pool" "pass" {
  allow_unauthenticated_identities = false

  cognito_identity_providers {
    client_id               = "CLIENT_ID_HERE"
    provider_name           = "COGNITO_USER_POOL_PROVIDER_NAME"
    server_side_token_check = true
  }

  # Example roles, adjust according to your requirements
  # For demonstration, assuming you have already created the IAM roles
  # aws_iam_role.authenticated_role and aws_iam_role.unauthenticated_role
  # Replace with your actual role ARNs
  # authenticated_role_arn   = aws_iam_role.authenticated_role.arn
  # unauthenticated_role_arn = aws_iam_role.unauthenticated_role.arn
}",
  "fix_summary": "Added a cognito_identity_providers block to restrict access and commented out role ARNs to be configured according to the user's IAM roles."
}
